import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火地晋","description":"周易折中 - 火地晋","frontmatter":{"title":"火地晋","description":"周易折中 - 火地晋"},"headers":[],"relativePath":"zh/classics/zhezhong/041.md","filePath":"zh/classics/zhezhong/041.md"}'),h={name:"zh/classics/zhezhong/041.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火地晋" tabindex="-1">火地晋 <a class="header-anchor" href="#火地晋" aria-label="Permalink to “火地晋”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈晋〉序卦：“物不可以终壮，故受之以晋。晋者，进也。物无壮而终止之理，既盛壮则必进，晋所以继大壮也。为卦离在坤上，明出地上也。日出于地，升而益明，故为晋。晋进而光明盛大之意也。凡物渐盛为进，故《彖》云：‘晋，进也。’卦有有徳者，有无徳者，随其宜也。乾坤之外，云元亨者固有也，云利贞者，所不足而可以有功也。有不同者，革、渐是也。随卦可见晋之盛，而无徳者无用有也。晋之明盛，故更不言亨，顺乎大明，无用戒正也。”</p><p>晋 康侯用锡马蕃庶，昼日三接</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>晋，进也。康侯，安国之侯也。锡马蕃庶，昼日三接，言多受大赐而显被亲礼也。盖其为卦上离下坤，有日出地上之象，顺而丽乎大明之德。又其变自观而来，为六四之柔进而上行以至于五，占者有是三者，则亦当有是宠也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>晋为进盛之时，大明在上，而下体顺附，诸侯承王之象也。故为康侯，康侯者，治安之侯也。上之大明而能司德以顺附，治安之侯也。故受其𠖥数，锡之马众多也（车马重赐也），蕃庶（众多也）。不惟锡与之厚，又见亲礼，昼日之中至于三接，言宠遇之至也。晋进盛之时，上明下顺，君臣相得。在上而言，则进于明盛；在臣而言，则进升高显，受其光宠也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰：晋卦取名之义与大有略相类。大有火在天上，君道也；晋明出地上，臣道也。以人臣之进独备一卦之义，则臣之道至大者，非康侯安足以当之。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>《易》有晋、升、渐三卦，皆同为进义而有别。晋如日之方出，其义最优；升如木之方生，其义次之；渐如木之既生而以渐高大，其义又次之。观其彖辞，皆可见矣。</p><p>象曰：明出地上，晋；君子以自昭明德</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>昭明之也</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>昭明之也。传曰：“昭德塞违，昭其度也。”君子观明出地上而益明盛之象，而以自昭其明德，去蔽致知。昭明德于己也，明明德于天下，昭明德于外也。明明德在己，故云“自昭”。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰：至健莫如天，君子以之自强；至明莫如日，君子以之自昭。</p></li><li><p>俞氏琰曰：明德，君子固有之德也。自昭者，自有此德而自明之也。人德本明，人欲蔽之，不能不少昏昧，其本然之明固未尝息。知所以自明，则本然之明如日之出地，而其昭著初无增减也。大学所谓“明明德”，所谓“自明”，与此同旨。</p></li></ul><p>彖曰：晋，进也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：晋以日之进言，与升、渐木之进不同。日出地上，其明进而盛。升、渐虽亦有进义，而无明盛之象。</li></ul><p>明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，昼日三接也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦象、卦德、卦变释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>晋，进也，明进而盛也。明出于地，益进而盛，故为晋。所以不谓之进者，进谓前进，不能包明盛之义。明出地上，离在坤上也。坤丽于离，以顺丽于大明，顺德之臣上附于大明之君也。柔进而上行，凡卦离在上者，柔居君位，多云柔进而上行（噬嗑、睽、鼎是也）。六五以柔居君位，明而顺丽，为能待下宠遇亲密之义，是以为康侯用锡马蕃庶，昼日三接也。大明之君安天下者也，诸侯能顺附天子之明德，是康民安国之侯也，故谓之康侯。是以享宠锡而见亲礼，昼日之闲三接见于天子也。不曰公卿而曰侯，天子治于上者也，诸侯治于下者也。在下而顺附于大明之君，诸侯之象也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：虽一卦名晋，而五爻为主，故言柔进而上行也。</p></li><li><p>郭氏雍曰 ：顺而丽乎大明，柔进而上行，康侯之德也。其德柔顺而明，故下能康一国之民而为之主，上能致王者之宠而锡马蕃庶，昼日三接也。</p></li><li><p>项氏安世曰 ：三女之卦，独离柔在上为得尊位，大中而行之，故谓之上行。巽在六四例谓之上合，上同兑在上六例谓之上穷，皆不得为上行也。</p></li><li><p>王氏申子曰 ：六十四卦离上者八，专取六五一爻以为成卦之主者二，晋、大有也。大有曰“柔得尊位大中而上下应之”，晋则曰“柔进而上行”，是专以康侯之晋者当此一卦之义矣。</p></li><li><p>吴氏曰慎曰 ：晋、咸《彖》传文意正同，卦象数句在卦名之下，卦辞之上，是既用以释卦名，而即以之释卦辞，故用“是以”二字接下。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>离之德为丽、为明，是明与丽皆离也。顺而丽乎大明，盖以顺德为本而为大明所附丽，则明者离而丽者亦离矣。若曰“以顺而附丽于大明”，则丽字乃为坤所借用，其义不亦赘乎？火之为物不能孤行也，必有所附，犹人心之明不可孤行也，必有所附。离曰“畜牝牛”者，明附于顺也。睽、旅之《彖》亦然，皆以说止为主而明附之也。此文义之误，不可不正。</p><p>/books/106/35/1.html</p><p>初六 晋如摧如，贞吉，罔孚裕无咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>以阴居下，应不中正，欲进见摧之象。占者如是而能守正则吉，设不为人所信，亦当处以宽裕，则无咎也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>初居晋之下，进之始也。晋如，升进也；摧如，抑退也。于始进而言，遂其进不遂其进，惟得正则吉也。罔孚者，在下而始进，岂遽能深见信于上？苟上未见信，则当安中自守，雍容宽裕，无急于求上之信也。苟欲信之心切，非汲汲以失其守则，悻悻以伤于义矣，皆有咎也。故裕则无咎，君子处进退之道也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏安石曰：初六以柔进，君子也。度礼义以进退者也。常人不见孚，则或急于进以求有为，或急于退则怼上之不知。孔子曰：“我待价者也。”此罔孚而裕于进也。孟子乆于齐，此罔孚而裕于退也。</p></li><li><p>朱子语类：问：初六“晋如摧如”象也，“贞吉”占辞。 曰：“罔孚裕无咎”，又是解上两句，恐“贞吉”说不明，故又晓之。</p></li><li><p>问：初六“晋如摧如”象也，“贞吉”占辞。 曰：“罔孚裕无咎”，又是解上两句，恐“贞吉”说不明，故又晓之。</p></li><li><p>胡氏炳文曰：进之初，人多有未信者。然摧如在彼，而吾不可以不正；罔孚在人，而吾不可以不裕。贞与裕，皆戒辞也。</p></li></ul><p>象曰：晋如摧如，独行正也；裕无咎，未受命也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初居下位，未有官守之命</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>无进无抑，唯独行正道也。寛裕则无咎者，始欲进而未当位故也。君子之于进退，或迟或速，唯义所当，未尝不裕也。圣人恐后之人不达寛裕之义，居位者废职失守以为裕，故特云初六裕则无咎者，始进未受命，当职任故也。若有官守不信于上而失其职，一日不可居也。然事非一概，久速唯时，亦容有为之兆者。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏曰：君子之于正，不可以人之不见知而改其度。</p></li><li><p>张氏振渊曰：独行正是原所以见摧之故。大凡君子处世，枉己易合，直道难容，惟正所以见摧，然安可因摧而自失其正？正与爻互相发明。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>未受命与临九二同。临、晋皆君子道长向用之卦也。然君子无急于乘势趋时之意，当其临也，至诚感物如忘其势；当其进也，守道优游若将终身。然故一则曰“未顺命”，一则曰“未受命”。</p><p>六二：晋如愁如，贞吉。受兹介福，于其王母。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>六二中正，上无应援，故欲进而愁。占者如是而能守正则吉，而受福于王母也。王母指六五，盖享先妣之吉占，而凡以阴居尊者皆其类也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>六二在下，上无应援，以中正柔和之德，非强于进者也。故于进为可忧愁，谓其进之难也。然守其贞正则当得吉，故云“晋如愁如，贞吉”。王母，祖母也，谓阴之至尊者，指六五也。二以中正之道自守，虽上无应援不能自进，然其中正之德乆而必彰。上之人自当求之，盖六五大明之君与之同德，必当求之，加以宠禄，受介福于王母也。介，大也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：小过六二曰“遇其妣”，彼言祖妣即此言王母也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>二五相应者也，以阴应阳，以阳应阴，则有君臣之象；以阴应阴，则有妣妇之象。不曰母而曰王母者，礼重昭穆，故孙祔于祖，则孙妇祔于祖姑。盖以昭穆相配，易爻以相配喻相应也。此明其为王母，而小过只言妣，蒙上过其祖之文尔。六五卦之主，而二应之，故有受福之义。</p><p>象曰：受兹介福，以中正也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>受兹介福，以中正之道也。人能守中正之道，久而必亨，况大明在上而同德，必受大福也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰：六二以柔顺处乎众阴而独无应，是不见知也。故晋如愁如，然居中守正，素位而行，鬼神其福之矣。诗曰：“靖其尔位，好是正直，神之听之，介尔景福。”此之谓也。</p></li><li><p>何氏楷曰：《尔雅》云：“父之妣为王母。”小过六二遇妣，即此言王母。二五德同位应，二受介福，以其履中得正也。</p></li></ul><p>六三：众允，悔亡。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>三不中正，宜有悔者。以其与下二阴皆欲上进，是以为众所信，而悔亡也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>以六居三，不得中正，宜有悔咎。而三在顺体之上，顺之极者也。三阴皆顺上者，是三之顺上与众同志，众所允从，其悔所以亡也。有顺上向明之志，而众允从之，何所不利？或曰：“不由中正而与众同，得为善乎？”曰：“众所允者，必至当也。况顺上之大明，岂有不善？”是以悔亡，盖亡其不中正之失矣。古人曰：“谋从众，则合天心。”</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰 ：“愼曰：‘初罔孚，未信也；三众允，见信也。’信于下，斯信于上，故弗信乎友，弗获于上矣。”</li></ul><p>象曰：众允之志，上行也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>上行上顺，丽于大明也。上从大明之君，众志之所同也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏过曰：初之罔孚，众未允也；二之愁如，犹有悔也；三德孚于众，进得所愿而悔亡也。</li></ul><p>九四：晋如鼫鼠，贞厉。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>不中不正，以窃高位，贪而畏人，盖危道也。故为鼫鼠之象，占者如是，虽正亦危也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>以九居四，非其位也。非其位而居之，贪据其位者也。贪处高位，既非所安，而又与上同德，顺丽于上。三阴皆在已下，势必上进，故其心畏忌之。贪而畏人者，鼫鼠也。故云“晋如鼫鼠”，贪于非据而存畏忌之心。贞固守此，其危可知。言贞厉者，开有改之道也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：“晋之道以顺而丽乎大明，以柔进而上行，皆主乎顺者也。三虽不正，以其能顺，故得其志而上行。四虽已进乎上，以其失柔顺之道，故如鼫鼠之穷而不得遂。”</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此卦以彖辞观之，则九四以一阳而近君，康侯之位也。参之爻义，反不然者，盖卦义所主在柔，则刚正与时义相反。当晋时，居高位而失静正之道，乖退让之节，贪而畏人，则非鼫鼠而何？贞厉者，戒其以持禄保位为常，而不知进退之义也。</p><p>象曰：鼫鼠贞厉，位不当也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>贤者以正德宜在高位，不正而处高位，则为非据。贪而惧失，则畏人，固处其地危可知也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰：履非其位，固其宠禄。鼫鼠之志，窃食黍稷而已。</li></ul><p>六五：悔亡，失得勿恤，往吉，无不利。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴居阳，宜有悔矣。以大明在上，而下皆顺从，故占者得之，则其悔亡。又一切去其计功谋利之心，则往吉而无不利也。然亦必有其德，乃应其占耳。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>六以柔居尊位，本当有悔。以大明在上而下皆顺附，故其悔得亡也。下既同德顺附，当推诚委任，尽众人之才，通天下之志，勿复自任其明，恤其失得。如此而往，则吉而无不利也。六五大明之主，不患其不能明照，患其用明之过，至于察察，失委任之道。故戒以失得勿恤也。夫私意偏任不察，则有蔽；尽天下之公，岂当复用私察也？</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰 ：阳为躁动，阴为静止。三五阳位，以阴居之，能节其动，故爻辞不称晋而皆曰悔亡。</p></li><li><p>石氏介曰 ：以道自任，得之自是，失之自是，曾不以介意。小人患得患失，恤也。</p></li><li><p>胡氏炳文曰 ：事有不必忧者勿恤，寛之之辞也；有不当忧者勿恤，戒之之辞也。此曰“失得勿恤”，戒辞明矣。盖当晋之时，易有患得患失之心。才柔又易有失得之累，大明在上，用其明于所当为，不当用其明于计功谋利之私也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>彖辞言康侯之被遇，而传以柔进上行释之，则圣人之意以此爻当康侯而为卦主明矣。盖凡卦皆有主，其合于彖辞者是也。九四高位而爻辞不善，如此则彖辞之义诚非六五不足以当之。晋如鼫鼠者，患得患失，鄙夫之行也；失得勿恤者，竭诚尽忠，君子之志也。</p><p>象曰：失得勿恤，往有庆也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以大明之德得下之附，推诚委任，则可以成天下之大功，是往而有福庆也。</p><p>上九：晋其角，维用伐邑，厉吉无咎，贞吝。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>角刚而居上，上九刚进之极，有其象矣。占者得之，而以伐其私邑，则虽危而吉，且无咎。然以极刚治小邑，虽得其正，亦可吝矣。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>角刚而居上之物，上九以刚居卦之极，故取角为象。以阳居上，刚之极也，在晋之上，进之极也。刚极则有强猛之过，进极则有躁急之失。以刚而极于进，失中之甚也，无所用而可，维独用于伐邑，则虽厉而吉，且无咎也。伐四方者，治外也；伐其居邑者，治内也。言伐邑，谓内自治也。人之自治，刚极则守道愈固，进极则迁善愈速。如上九者，以之自治，则虽伤于厉而吉，且无咎也。严厉非安和之道，而于自治则有功也。复云贞吝，以尽其义，极于刚进，虽自治有功，然非中和之德，故以贞正之道为可吝也。不失中正为贞。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：无可进而进，惟伐邑于内则可矣。如君子则知止也。</p></li><li><p>王氏宗传曰 ：晋之上九，晋至于角，无所复进矣。惟能自反自克而内自治焉，则知危厉自警而𫉬吉矣。此所以无刚进之咎也。</p></li><li><p>朱子语类 （看伯丰与庐陵问答内晋卦伐邑说）曰：晋上九贞吝，吝不在克治，正以其克治之难而言其合下有此吝耳。贞吝之义，只云贞固守此，则吝不应于此独云，于正道为吝也。</p></li><li><p>项氏安世曰 ：晋好柔而恶刚，故九四上九皆以厉言之。四进而非其道，故为鼫鼠；上已穷而犹晋，故为晋其角。</p></li><li><p>陆氏振奇曰 ：当晋之时，圣人最喜用柔而不用刚，故四阴吉悔亡，二阳厉且吝也。案：晋其角者，是知进而不知退者也。知进而不知退者，危道也。然亦有时事使然而进退甚难者，惟内治其私，反身无过，如居家则戒子弟戢僮仆，居官则杜交私严假托，皆伐邑之谓也。如此，则虽危而吉无咎矣。若以进为常，纵未至于危也，宁无愧于心乎？</p></li></ul><p>象曰：维用伐邑，道未光也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>维用伐邑，既得吉而无咎，复云贞吝者，其道未光大也。以正理言之，尤可吝也。夫道既光大，则无不中正，安有过也？今以过刚自治，虽有功矣，然其道未光大，故亦可吝。圣人言尽善之道，案道未光乃推原所以伐邑之故。盖进之极，则于道必未光也。如势位重，则有居成功之嫌；爵禄羁，则失独行愿之志。故必克治其私，然后高而不危，免于亢悔也。夬五之“未光”同。</p><p>总论</p><ul><li><p>丘氏富国曰 ：晋进也，柔进而上行也。故卦专主柔进为义。六爻四柔二刚，六五一柔自四而升，已进者也，故往吉无不利。下坤三柔皆欲进者，而九四以刚间之，故有晋如鼫鼠之象。</p></li><li><p>赵氏汝腾曰 ：下三爻皆柔顺而坤体，故初二吉三悔亡。四上以阳不当位，故厉且吝。惟五以柔明居尊位，故往吉无不利也。</p></li><li><p>龚氏焕曰 ：晋卦诸爻皆以进为义，初二三五柔之进，四与上刚之进也。四阴二阳，阴多吉而阳多厉者，晋以柔顺为善，刚强则躁矣。故彖传曰：“顺而丽乎大明，柔进而上行。”卦之得名，其亦以柔为主与？</p></li></ul>',114)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
